python - <<'PY'
import numpy as np
from PIL import Image
for c in ['front','left','right','topview']:
 im=np.array(Image.open(f'/app/runs/approach_gray_nut_settled/last/{c}.jpg'))
 d=np.load(f'/app/runs/approach_gray_nut_settled/depth_{c}.npy')[-1].astype(float)
 mask=(im.max(2)-im.min(2)<22)&(im.mean(2)>65)&(im.mean(2)<155)
 if c=='front':
  yy,xx=np.indices(mask.shape); mask &= (yy>85)&(yy<155)&(xx>95)&(xx<220)
 ys,xs=np.where(mask)
 print('\n',c,'gray count',len(xs))
 if len(xs):
  cells={}
  for x,y in zip(xs,ys):
   k=(x//8,y//8);cells[k]=cells.get(k,0)+1
  print(sorted(cells.items(),key=lambda z:-z[1])[:10])
  for x,y in [(160,120),(170,120),(160,100),(158,100),(150,100),(170,100)]:
   if 0<=x<320 and 0<=y<240: print((x,y),im[y,x].tolist(),round(d[y,x],3))
